    if (kind === 'paid') await invoiceApi.markPaid(invoice.id);
    if (kind === 'overdue') await invoiceApi.markOverdue(invoice.id);
    await load();
  }

  async function downloadPdf(invoice: Invoice) {
    await invoiceApi.downloadPdf(invoice.id);
  }

